        :root {
            --primary-color: #0066cc;
            --primary-hover: #0052a3;
            --bg-color: #f4f7f9;
            --card-bg: #ffffff;
            --text-color: #1a1a1a;
            --text-secondary: #4b5563;
            --border-color: #d1d5db;
            --focus-ring: rgba(0, 102, 204, 0.4);
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .container {
            width: 100%;
            max-width: 450px;
            padding: 20px;
        }

        .card {
            background: var(--card-bg);
            border-radius: 12px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            padding: 32px;
        }

        h1 {
            font-size: 1.5rem;
            font-weight: 700;
            margin-bottom: 24px;
            color: var(--text-color);
        }

        .form-field {
            margin-bottom: 24px;
        }

        fieldset {
            border: none;
            padding: 0;
            margin: 0;
        }

        legend {
            font-size: 1.125rem;
            font-weight: 600;
            margin-bottom: 16px;
            color: var(--text-color);
            line-height: 1.4;
        }

        .radio-options {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .radio-option {
            display: flex;
            align-items: center;
            cursor: pointer;
            padding: 12px 16px;
            border: 1px solid var(--border-color);
            border-radius: 8px;
            transition: all 0.2s ease;
        }

        .radio-option:hover {
            border-color: var(--primary-color);
            background-color: rgba(0, 102, 204, 0.02);
        }

        .radio-option:has(input:checked) {
            border-color: var(--primary-color);
            background-color: rgba(0, 102, 204, 0.05);
            box-shadow: 0 0 0 1px var(--primary-color);
        }

        input[type="radio"] {
            appearance: none;
            width: 20px;
            height: 20px;
            border: 2px solid var(--border-color);
            border-radius: 50%;
            margin-right: 12px;
            position: relative;
            cursor: pointer;
            outline: none;
            flex-shrink: 0;
        }

        input[type="radio"]:checked {
            border-color: var(--primary-color);
        }

        input[type="radio"]:checked::after {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 10px;
            height: 10px;
            background-color: var(--primary-color);
            border-radius: 50%;
        }

        input[type="radio"]:focus-visible {
            box-shadow: 0 0 0 3px var(--focus-ring);
        }

        .label-text {
            font-size: 1rem;
            font-weight: 500;
        }

        button[type="submit"] {
            width: 100%;
            background-color: var(--primary-color);
            color: white;
            border: none;
            padding: 12px 24px;
            font-size: 1rem;
            font-weight: 600;
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.2s ease;
        }

        button[type="submit"]:hover {
            background-color: var(--primary-hover);
        }

        button[type="submit"]:focus-visible {
            outline: 2px solid var(--primary-color);
            outline-offset: 2px;
        }

        .success-message {
            margin-top: 16px;
            padding: 12px;
            background-color: #d1fae5;
            color: #065f46;
            border-radius: 8px;
            text-align: center;
            font-weight: 500;
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState } = React;

        function NotificationForm() {
            const [selectedOption, setSelectedOption] = useState('');
            const [submitted, setSubmitted] = useState(false);

            const options = [
                { id: 'email', label: 'Email' },
                { id: 'sms', label: 'SMS' },
                { id: 'push', label: 'Push Notifications' }
            ];

            const handleSubmit = (e) => {
                e.preventDefault();
                if (selectedOption) {
                    setSubmitted(true);
                    // Reset success message after 3 seconds
                    setTimeout(() => setSubmitted(false), 3000);
                }
            };

            return (
                <main className="container">
                    <div className="card">
                        <h1>Account Settings</h1>
                        <form onSubmit={handleSubmit}>
                            <div className="form-field">
                                <fieldset>
                                    <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
                                    <div className="radio-options">
                                        {options.map((option) => (
                                            <label key={option.id} className="radio-option" htmlFor={option.id}>
                                                <input
                                                    type="radio"
                                                    id={option.id}
                                                    name="notification-pref"
                                                    value={option.id}
                                                    required
                                                    checked={selectedOption === option.id}
                                                    onChange={(e) => setSelectedOption(e.target.value)}
                                                />
                                                <span className="label-text">{option.label}</span>
                                            </label>
                                        ))}
                                    </div>
                                </fieldset>
                            </div>
                            <button type="submit">Save Preferences</button>
                        </form>
                        {submitted && (
                            <div className="success-message" role="status">
                                Preferences saved successfully!
                            </div>
                        )}
                    </div>
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<NotificationForm />);
    </script>
</body>
</html>
