    <a href="#main-content" class="skip-link">Skip to main content</a>
    <div id="root"></div>

    <script type="text/babel">
        const { useState } = React;

        function NotificationForm() {
            const [selectedOption, setSelectedOption] = useState('');
            const [submitted, setSubmitted] = useState(false);

            const options = [
                { id: 'email', label: 'Email' },
                { id: 'sms', label: 'SMS' },
                { id: 'push', label: 'Push Notifications' }
            ];

            const handleSubmit = (e) => {
                e.preventDefault();
                if (selectedOption) {
                    setSubmitted(true);
                    // Reset success message after 3 seconds
                    setTimeout(() => setSubmitted(false), 5000);
                }
            };

            return (
                <main className="container" id="main-content">
                    <div className="card">
                        <h1>Account Settings</h1>
                        <form onSubmit={handleSubmit}>
                            <div className="form-field">
                                <fieldset>
                                    <legend>How do you prefer to receive notifications? <span className="required-marker" aria-hidden="true">*</span></legend>
                                    <p id="group-help" className="sr-only">Selecting an option is required.</p>
                                    <div className="radio-options">
                                        {options.map((option) => (
                                            <label key={option.id} className="radio-option" htmlFor={option.id}>
                                                <input
                                                    type="radio"
                                                    id={option.id}
                                                    name="notification-pref"
                                                    value={option.id}
                                                    required
                                                    aria-describedby="group-help"
                                                    checked={selectedOption === option.id}
                                                    onChange={(e) => setSelectedOption(e.target.value)}
                                                />
                                                <span className="label-text">{option.label}</span>
                                            </label>
                                        ))}
                                    </div>
                                </fieldset>
                            </div>
                            <button type="submit">Save Preferences</button>
                        </form>
                        {submitted && (
                            <div className="success-message" role="status">
                                Preferences saved successfully!
                            </div>
                        )}
                    </div>
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<NotificationForm />);
    </script>
</body>
</html>
